INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art1', '{"id":"art1","title":"เทคนิคการให้น้ำทุเรียนช่วงเตรียมทำใบ","category":"การดูแลรักษา","image":"/images/articles/article_watering_1778037948644.avif","status":"published","createdAt":"2026-11-01T02:25:48.611Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"ระยะเตรียมทำใบเป็นช่วงสำคัญที่ต้องเพิ่มการให้น้ำให้สม่ำเสมอ เพื่อให้ใบออกสวยงามและสม่ำเสมอ การให้น้ำแบบเคาะหรือหยดน้ำ 2-3 ครั้งต่อสัปดาห์จะช่วยให้พืชมีความชื้นเพียงพอ\n\nการให้น้ำในช่วงนี้ควรเน้นที่ความชื้นของดินเป็นหลัก ไม่ควรปล่อยให้ดินแห้งแตกระแหง เพราะจะทำให้การแตกใบอ่อนไม่สม่ำเสมอ นอกจากนี้ควรมีการเสริมปุ๋ยทางใบร่วมด้วยเพื่อให้ใบมีความสมบูรณ์สูงสุด"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art2', '{"id":"art2","title":"รับมือโรคไฟทอปธอร่า หน้าฝนนี้ต้องรอด","category":"โรคและแมลง","image":"/images/articles/article_disease_1778037967060.avif","status":"published","createdAt":"2026-11-01T02:25:48.612Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"โรคไฟทอปธอร่าเป็นโรคร้ายแรงที่อาจทำให้สูญเสียผลผลิตได้ 50-80% วิธีป้องกันคือการใช้ปุ๋ยสมดุล เพิ่มการระบายอากาศ และใช้สารเคมีป้องกันอย่างถูกต้อง\n\nหัวใจสำคัญคือการจัดการน้ำในสวนไม่ให้ท่วมขัง และการตรวจสอบแผลตามลำต้นอย่างสม่ำเสมอ หากพบแผลควรทำการถากเนื้อไม้ที่เสียออกและทาด้วยสารป้องกันเชื้อราทันที"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art3', '{"id":"art3","title":"แนวโน้มราคาทุเรียนส่งออก ปี 2026","category":"การตลาด","image":"/images/articles/article_market_1778038017547.avif","status":"published","createdAt":"2026-11-01T02:25:48.612Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"ราคาทุเรียนปี 2026 คาดว่าจะสูงขึ้นจากปีที่แล้ว เนื่องจากอุปสงค์จากตลาดเอเชียและจีนที่เพิ่มขึ้น ราคาประมาณ 100-150 บาทต่อกิโลกรัมสำหรับคุณภาพเกรด A\n\nเกษตรกรควรเน้นการทำทุเรียนคุณภาพพรีเมียมและมีการรับรองมาตรฐาน GAP เพื่อให้ได้ราคาสูงสุดและเป็นที่ต้องการของตลาดส่งออก"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art4', '{"id":"art4","title":"วิธีสังเกตดอกทุเรียนระยะไข่ปลา","category":"การสังเกต","image":"/images/articles/article_flowering_1778039300000_1778039688657.avif","status":"published","createdAt":"2026-11-01T02:25:48.612Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"ระยะไข่ปลาเป็นช่วงที่ดอกเข้าชิดกันเหมือนไข่ปลา ลักษณะเพศเริ่มแตกต่างชัดเจน ควรเน้นการให้น้ำและปุ๋ยให้สม่ำเสมอในช่วงนี้\n\nระวังอย่าให้น้ำมากเกินไปเพราะอาจทำให้ดอกหลุดร่วงได้ ควรให้น้ำในปริมาณที่พอเหมาะเพื่อให้ดอกพัฒนาไปสู่ระยะมะเขือพวงได้อย่างสมบูรณ์"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art5', '{"id":"art5","title":"ปุ๋ยสูตรไหนเหมาะกับระยะขยายขนาดผล","category":"การให้ปุ๋ย","image":"/images/articles/article_fertilizer_1778039300000_1778039705364.avif","status":"published","createdAt":"2026-11-01T02:25:48.612Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"ในระยะขยายขนาดผล ควรใช้ปุ๋ยที่มีแคลเซียมและโพแทสเซียมสูง เช่น NPK 5:10:20 หรือสูตรเฉพาะสำหรับผลไม้ให้ 2-3 ครั้งต่อเดือน\n\nการใส่ปุ๋ยในช่วงนี้จะช่วยให้เนื้อทุเรียนมีคุณภาพดี รสชาติหวาน และมีน้ำหนักผลที่ได้มาตรฐาน"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art6', '{"id":"art6","title":"การตัดแต่งกิ่งเตรียมพร้อมสำหรับฤดูกาลใหม่","category":"การดูแลรักษา","image":"/images/articles/article_pruning_1778039300000_1778039722927.avif","status":"published","createdAt":"2026-11-01T02:25:48.612Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"การตัดแต่งกิ่งช่วยกระตุ้นการออกใบและดอกใหม่ ตัดกิ่งที่อ่อนแอหรือเก่า และปล่อยให้พืชมีรูปทรงสวยงาม ลักษณะปิรามิด\n\nการตัดแต่งกิ่งที่ถูกต้องจะช่วยให้แสงแดดส่องถึงโคนต้น ลดการสะสมของโรคและแมลง และช่วยให้พืชใช้สารอาหารได้อย่างมีประสิทธิภาพ"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art7', '{"id":"art7","title":"เลือกใช้สารเคมีในสวนทุเรียนอย่างปลอดภัย","category":"สารเคมี","image":"/images/articles/article_disease_1778037967060.avif","status":"published","createdAt":"2026-11-01T02:25:48.612Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"การเลือกใช้สารเคมีควรเริ่มจากการสำรวจอาการจริงในสวนก่อนเสมอ แยกให้ชัดว่าเป็นโรค แมลง หรือภาวะขาดธาตุอาหาร เพื่อเลือกกลุ่มสารให้ตรงปัญหาและลดการใช้เกินจำเป็น\n\nอ่านฉลาก อัตราผสม ระยะปลอดภัยก่อนเก็บเกี่ยว และอุปกรณ์ป้องกันทุกครั้ง ควรสลับกลุ่มสารตามคำแนะนำบนฉลากเพื่อลดการดื้อยา และหลีกเลี่ยงการพ่นช่วงลมแรงหรือก่อนฝนตก","affiliateTitle":"เพิ่มชื่อสารเคมีที่แนะนำ","affiliateUrl":""}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('articles', 'art8', '{"id":"art8","title":"เช็กความพร้อมสวนก่อนเข้าฤดูฝน","category":"การดูแลรักษา","image":"/images/articles/article_pruning_1778039300000_1778039722927.avif","status":"published","createdAt":"2026-11-01T02:25:48.612Z","updatedAt":"2026-11-01T02:25:48.612Z","content":"ก่อนเข้าฤดูฝนควรสำรวจทางน้ำ ร่องระบายน้ำ และพื้นที่ต่ำในสวนให้พร้อม เพราะน้ำขังเป็นปัจจัยสำคัญที่กระตุ้นโรครากเน่าโคนเน่าในทุเรียน โดยเฉพาะต้นที่มีแผลหรือระบบรากอ่อนแอ\n\nควรตัดแต่งกิ่งที่แน่นเกินไป เก็บเศษใบและผลร่วงออกจากโคนต้น และตรวจสภาพดินหลังฝนตกทุกครั้ง หากพบจุดที่น้ำไหลช้าหรือขังนาน ควรปรับร่องระบายทันทีเพื่อลดความเสี่ยงก่อนเกิดปัญหาใหญ่"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('products', 'prod1', '{"id":"prod1","name":"สารป้องกันเชื้อราในสวนทุเรียน","category":"สารเคมี","image":"/images/articles/article_disease_1778037967060.avif","priceLabel":"ดูราคาล่าสุด","description":"ช่วยลดความเสี่ยงโรคจากเชื้อราในช่วงอากาศชื้นและหน้าฝน","affiliateUrl":"","status":"active","createdAt":"2026-11-01T02:25:48.618Z","updatedAt":"2026-11-01T02:25:48.618Z"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('products', 'prod2', '{"id":"prod2","name":"ปุ๋ยระยะขยายผล","category":"ปุ๋ย","image":"/images/articles/article_fertilizer_1778039300000_1778039705364.avif","priceLabel":"ดูรายละเอียด","description":"เหมาะกับช่วงบำรุงผล เน้นความสมบูรณ์และการเพิ่มน้ำหนักผล","affiliateUrl":"","status":"active","createdAt":"2026-11-01T02:25:48.618Z","updatedAt":"2026-11-01T02:25:48.618Z"}');
INSERT OR IGNORE INTO content (kind, id, data) VALUES ('products', 'prod3', '{"id":"prod3","name":"อุปกรณ์พ่นยา","category":"อุปกรณ์","image":"/images/articles/article_pruning_1778039300000_1778039722927.avif","priceLabel":"เช็กราคา","description":"ใช้งานสะดวกสำหรับงานพ่นยา ดูแลทรงพุ่ม และจัดการงานในสวน","affiliateUrl":"","status":"active","createdAt":"2026-11-01T02:25:48.618Z","updatedAt":"2026-11-01T02:25:48.618Z"}');
